@@ -85,3 +210,216 @@ async fn get_l1_block_for_batch(

     Ok(None)
 }
+
+#[cfg(test)]
+mod tests {
+    use super::{AnswerCache, finalized_floor, pick_seed};
+
+    #[test]
+    fn empty_cache_seeds_zero() {
+        let cache = AnswerCache::new();
+        assert_eq!(cache.seed(0), 0);
+        assert_eq!(cache.seed(100), 0);
+        assert_eq!(cache.seed(u64::MAX), 0);
+    }
+
+    #[test]
+    fn cache_seeds_equal_or_later_target() {
+        let cache = AnswerCache::new();
+        cache.update(100, 50);
+        // Same target: the previous answer is exactly the answer.
+        assert_eq!(cache.seed(100), 50);
+        // Later target: monotonic timestamps mean the answer can only move up, so 50
+        // is still a true lower bound.
+        assert_eq!(cache.seed(200), 50);
+    }
+
+    #[test]
+    fn cache_refuses_earlier_target() {
+        let cache = AnswerCache::new();
+        cache.update(100, 50);
+        // Block 50 is only proven to be <= the answer for targets >= 100. For an
+        // earlier target it could sit *above* the true answer, and an over-high `lo`
+        // would silently skip real blocks at the finality call sites.
+        assert_eq!(cache.seed(50), 0);
+        assert_eq!(cache.seed(99), 0);
+    }
+
+    #[test]
+    fn cache_update_is_a_ratchet() {
+        let cache = AnswerCache::new();
+        cache.update(200, 90);
+        // An older/smaller-target update arriving late (two concurrent epochs finishing
+        // out of order) must not regress the cache.
+        cache.update(100, 40);
+        // Still refuses anything below the ratcheted target...
+        assert_eq!(cache.seed(150), 0);
+        assert_eq!(cache.seed(199), 0);
+        // ...and still hands back the block for the ratcheted target and beyond.
+        assert_eq!(cache.seed(200), 90);
+        assert_eq!(cache.seed(250), 90);
+    }
+
+    #[test]
+    fn finalized_floor_rejects_head_at_or_past_target() {
+        // Finalized head already past the target: its block number may exceed the true
+        // answer, so it must never be used as a lower bound.
+        assert_eq!(finalized_floor(300, 900, 200), 0);
+        assert_eq!(finalized_floor(201, 900, 200), 0);
+        // Exactly at the target is rejected too: on a chain with non-decreasing (not
+        // strictly increasing) timestamps, an earlier block can carry the same second.
+        assert_eq!(finalized_floor(200, 900, 200), 0);
+    }
+
+    #[test]
+    fn finalized_floor_accepts_head_behind_target() {
+        // Finalized head strictly behind the target: provably < the answer.
+        assert_eq!(finalized_floor(100, 900, 200), 900);
+        assert_eq!(finalized_floor(199, 900, 200), 900);
+    }
+
+    #[test]
+    fn pick_seed_prefers_the_cache() {
+        // Cache usable: taken even though the finalized floor would also apply. The two
+        // are never combined - picking the larger of them would not be provably safe.
+        assert_eq!(pick_seed(50, Some((100, 900)), 200), 50);
+        // ...and taken even when the finalized head is past the target and unusable.
+        assert_eq!(pick_seed(50, Some((300, 900)), 200), 50);
+    }
+
+    #[test]
+    fn pick_seed_falls_back_to_finalized_when_cache_is_empty() {
+        assert_eq!(pick_seed(0, Some((100, 900)), 200), 900);
+    }
+
+    #[test]
+    fn pick_seed_is_zero_when_neither_source_is_usable() {
+        // Cache empty and finalized head past the target.
+        assert_eq!(pick_seed(0, Some((300, 900)), 200), 0);
+        // Cache empty and no finalized block at all (RPC error, or a node that does not
+        // serve the tag - Anvil devnets among them).
+        assert_eq!(pick_seed(0, None, 200), 0);
+    }
+
+    /// Mirrors the "first block at or after `target_ts`" search in
+    /// `find_block_by_timestamp_from` (lib.rs), including its head clamp and its
+    /// `lo.min(latest)` guard, so the seeding rules above can be checked against real
+    /// search behaviour without a provider. `timestamps[n]` is block `n`'s timestamp.
+    fn model_search(timestamps: &[u64], target_ts: u64, lo: u64) -> u64 {
+        let latest_num = (timestamps.len() - 1) as u64;
+        if target_ts >= timestamps[latest_num as usize] {
+            return latest_num;
+        }
+        let mut lo = lo.min(latest_num);
+        let mut hi = latest_num;
+        while lo < hi {
+            let mid = lo + (hi - lo) / 2;
+            if timestamps[mid as usize] < target_ts {
+                lo = mid + 1;
+            } else {
+                hi = mid;
+            }
+        }
+        lo
+    }
+
+    /// Ethereum-like: timestamps strictly increase.
+    fn l1_chain() -> Vec<u64> {
+        (0..64u64).map(|i| 1_000 + 12 * i).collect()
+    }
+
+    /// Arbitrum-like: timestamps are non-decreasing, three blocks per second.
+    fn l2_chain() -> Vec<u64> {
+        (0..48u64).map(|i| 1_000 + i / 3).collect()
+    }
+
+    #[test]
+    fn any_true_lower_bound_returns_the_unseeded_answer() {
+        // The whole safety argument for seeding: for every `lo` at or below the true
+        // answer, the seeded search returns exactly what an unseeded search returns.
+        for chain in [l1_chain(), l2_chain()] {
+            for target_ts in 995..1_020 {
+                let unseeded = model_search(&chain, target_ts, 0);
+                for lo in 0..=unseeded {
+                    assert_eq!(
+                        model_search(&chain, target_ts, lo),
+                        unseeded,
+                        "target {target_ts} seeded at {lo}"
+                    );
+                }
+            }
+        }
+    }
+
+    #[test]
+    fn an_over_high_lo_silently_returns_lo_itself() {
+        // Why the finality call sites need a *true* lower bound: seeding above the
+        // answer does not fail loudly, it returns the seed, and that block feeds
+        // `findBatchContainingBlock` directly.
+        let chain = l1_chain();
+        let target_ts = 1_100;
+        let answer = model_search(&chain, target_ts, 0);
+        assert_eq!(model_search(&chain, target_ts, answer + 5), answer + 5);
+    }
+
+    #[test]
+    fn finalized_floor_never_exceeds_the_true_answer() {
+        // Exhaustive over both chain shapes: whatever block the node reports as
+        // `finalized`, the floor derived from it is at or below the true answer.
+        for chain in [l1_chain(), l2_chain()] {
+            for target_ts in 995..1_020 {
+                let answer = model_search(&chain, target_ts, 0);
+                for (finalized_block, finalized_ts) in chain.iter().enumerate() {
+                    let seed = finalized_floor(*finalized_ts, finalized_block as u64, target_ts);
+                    assert!(
+                        seed <= answer,
+                        "target {target_ts}: floor {seed} from finalized block \
+                         {finalized_block} exceeds answer {answer}"
+                    );
+                    assert_eq!(model_search(&chain, target_ts, seed), answer);
+                }
+            }
+        }
+    }
+
+    #[test]
+    fn cached_seed_matches_the_unseeded_answer_on_strict_timestamps() {
+        // Targets arrive non-decreasing (epoch ends), each re-checked a few times (the
+        // dispatcher retries the same epoch every 30 minutes).
+        let chain = l1_chain();
+        let cache = AnswerCache::new();
+        for target_ts in [1_050u64, 1_050, 1_200, 1_200, 1_400, 1_700, 1_700] {
+            let unseeded = model_search(&chain, target_ts, 0);
+            let seeded = model_search(&chain, target_ts, cache.seed(target_ts));
+            assert_eq!(seeded, unseeded, "target {target_ts}");
+            cache.update(target_ts, seeded);
+        }
+    }
+
+    #[test]
+    fn cached_seed_stays_inside_the_target_second_on_repeated_timestamps() {
+        // Growing chain: `(len, target)` is "the chain has `len` blocks when the epoch
+        // end `target` is checked". The first check happens while the head still carries
+        // `target` itself, which is the one case where the cached answer can land above
+        // the *first* block bearing that timestamp.
+        let chain = l2_chain();
+        let cache = AnswerCache::new();
+        let mut saw_divergence = false;
+        for (len, target_ts) in [(12usize, 1_003u64), (24, 1_003), (24, 1_005), (48, 1_005)] {
+            let visible = &chain[..len];
+            let unseeded = model_search(visible, target_ts, 0);
+            let seeded = model_search(visible, target_ts, cache.seed(target_ts));
+            // Never earlier than the unseeded answer, and always the same timestamp -
+            // so the epoch-end block is still an at-or-after-epoch-end block, and the
+            // batch it resolves to is equal or later, i.e. conservative.
+            assert!(seeded >= unseeded, "target {target_ts}: {seeded} < {unseeded}");
+            assert_eq!(
+                visible[seeded as usize], visible[unseeded as usize],
+                "target {target_ts}: seeded block {seeded} left the target second"
+            );
+            saw_divergence |= seeded != unseeded;
+            cache.update(target_ts, seeded);
+        }
+        assert!(saw_divergence, "fixture no longer exercises the head-clamp case");
+    }
+}
